Definition cfull (c : core) : Prop := rfull (c_regs c).

Inductive eff_full : eff -> Prop :=
| FuDone : forall c, cfull c -> eff_full (EDone c)
| FuIllegal : forall c, eff_full (EIllegal c)
| FuDefIllegal : forall c, eff_full (EDefinedIllegal c)
| FuEcall : forall c, eff_full (EEcall c)
| FuEbreak : forall c, eff_full (EEbreak c)
| FuFault : forall c, eff_full (EFault c)
| FuLoad : forall n a k, (forall v, eff_full (k v)) -> eff_full (ELoad n a k)
| FuStore : forall n a v k, eff_full k -> eff_full (EStore n a v k).

Local Ltac core_tac :=
  unfold cfull, rset, fset, with_regs, with_fregs, with_pc, with_fcsr, with_resv,
         accrue, fwrite, inval_resv in *; simpl in *.

